// #81a5e9 רכיב העלאת מסמכים ותעודות — на шагах мастера (S-06 шаг 2, S-08 шаг 4) и изоляция между компаниями (AC5).
// @data: шаги мастера и документы — общие данные аккаунта ADMIN, тесты идут по одному.
import { test as base, expect, Page } from '@playwright/test';
import { test as multi } from '../../fixtures';
import { authState, openWizardStep, qaFile, qaName, restoreWizard, uploadItem } from '../helpers/tenderflow';

const DOCS_LABEL = 'מסמכים קבועים של החברה';

async function removeIfPresent(page: Page, fileName: string) {
  const btn = page.getByRole('button', { name: `הסרה: ${fileName}` });
  if (await btn.count()) {
    await btn.click();
    await expect(uploadItem(page, fileName)).toHaveCount(0);
  }
}

base.describe('רכיב העלאת מסמכים — פרופיל חברה', () => {
  base.describe.configure({ mode: 'serial' });
  base.use({ storageState: authState('admin') });
  base.afterEach(async ({ page }) => restoreWizard(page));

  base('אותו רכיב העלאה במסך מידע להתאמה ובמסך מסמכים קבועים #81a5e9 @desktop @data', async ({ page }) => {
    // Т11 / דרישה 10: компонент есть на S-06 и S-08 (S-09 — в upload-component-tender.spec.ts)
    await openWizardStep(page, 2);
    const s06 = page.getByLabel('מסמכים ותעודות תומכים', { exact: true });
    await expect(s06).toBeAttached();
    await expect(s06).toHaveAttribute('type', 'file');
    await expect(s06).toHaveAttribute('multiple', '');
    await expect(page.getByText('אפשר גם לגרור קבצים לכאן. PDF, Word, Excel או תמונה (JPG, PNG), עד 10MB לקובץ.')).toBeVisible();

    await openWizardStep(page, 4);
    await expect(page.getByLabel('סוג המסמך להעלאה')).toBeVisible();
    const s08 = page.getByLabel(DOCS_LABEL, { exact: true });
    await expect(s08).toBeAttached();
    await expect(s08).toHaveAttribute('type', 'file');
    await expect(s08).toHaveAttribute('multiple', '');
    await expect(page.getByText('אפשר גם לגרור קבצים לכאן. PDF, Word, Excel או תמונה (JPG, PNG), עד 10MB לקובץ.')).toBeVisible();
  });

  base('כשל רשת בזמן העלאה מציג מצב שגיאה ואפשרות הסרה #81a5e9 @desktop @data', async ({ page }) => {
    await openWizardStep(page, 4);
    const file = qaFile(qaName('upl-offline'), 'pdf');

    // Т6: обрыв соединения с хранилищем файлов во время загрузки
    await page.route('**/storage/v1/object/**', (route) => route.abort('internetdisconnected'));
    try {
      await page.getByLabel(DOCS_LABEL, { exact: true }).setInputFiles(file);
      const item = uploadItem(page, file.name);
      await expect(item).toContainText('ההעלאה נכשלה');
      await expect(item).toContainText('אין חיבור לשרת. נסו שוב.');
      await expect(page.getByRole('button', { name: `הסרה: ${file.name}` })).toBeVisible();
      await page.getByRole('button', { name: `הסרה: ${file.name}` }).click();
      await expect(item).toHaveCount(0);
    } finally {
      await page.unroute('**/storage/v1/object/**');
    }

    // Очистка: если запись о файле всё же сохранилась — удалить
    await openWizardStep(page, 4);
    await removeIfPresent(page, file.name);
  });
});

multi.describe('רכיב העלאת מסמכים — בידוד בין חברות', () => {
  multi.describe.configure({ mode: 'serial' });

  multi('קובץ של חברה A אינו מוצג לחברה B #81a5e9 #62038e @desktop @data', async ({ asUser }) => {
    const adminA = await asUser('admin');
    const adminB = await asUser('admin2');
    const file = qaFile(qaName('iso'), 'pdf');

    try {
      // Компания A загружает постоянный документ
      await openWizardStep(adminA, 4);
      await adminA.getByLabel(DOCS_LABEL, { exact: true }).setInputFiles(file);
      await expect(uploadItem(adminA, file.name).getByRole('status')).toHaveText('הועלה');

      // AC5 (#81a5e9) / изоляция (#62038e): компания B не видит файл компании A
      await openWizardStep(adminB, 4);
      await expect(adminB.getByLabel('סוג המסמך להעלאה')).toBeVisible(); // список документов B загружен
      await expect(adminB.getByText(file.name)).toHaveCount(0);
    } finally {
      await openWizardStep(adminA, 4);
      await removeIfPresent(adminA, file.name);
      await restoreWizard(adminB);
    }
  });
});
